   --chat-header-title-color: #FFF;
   --chat-header-icon-color: #FFF;

   /* 🌙 夜间：深灰色半透明底 + 白色字 */
   --unread-bg: rgba(100, 100, 100, 0.45);
   --unread-color: #FFFFFF;

   --timestamp-color: #959595;
   --date-divider-color: #959595;
   --narration-color: #959595;
   --system-msg-color: #959595;
   --na-bg: #292929FE;
   --na-bd: 0.7px solid #3B3B3B;

   /* === 回复预览栏 === */
   --reply-bar-accent: #AAA;
