   --trans-btn1: #5E5E5E;
   /* === 我方气泡 === */
   --bubble-me-bg: #28B561;
   --bubble-me-color: #04120A;
   /* === 对方气泡 === */
   --bubble-them-bg: #2C2C2C;
   --bubble-them-color: #DADADA;

   /* === 语音 === */
